// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Set;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.algebra.BindingSetAssignment;
import org.eclipse.rdf4j.query.algebra.QueryRoot;
import org.eclipse.rdf4j.query.impl.ListBindingSet;
import org.junit.jupiter.api.Test;

/**
 * A retained pipeline-cache template must carry {@code VALUES ... UNDEF} rows exactly as the source did: an unbound
 * cell is a {@code null} value in {@link ListBindingSet}, and the detached copy must tolerate it.
 */
class LmdbPipelinePlanCacheUndefRowsTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI A = VF.createIRI("urn:a");
	private static final IRI B = VF.createIRI("urn:b");

	@Test
	void retainedTemplateKeepsUndefRows() {
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(8, 1, 1024 * 1024L);
		LmdbPipelinePlanCache.Context context = context(17L);
		QueryRoot coldSource = valuesQuery(undefRows());

		LmdbPipelinePlanCache.Result cold = cache.getOrCompute(coldSource, context, context::revision, () -> {
			coldSource.setStringMetricPlanned(LmdbCascadesOptimizer.APPLIED_METRIC, "true");
			return coldSource;
		});
		QueryRoot hotSource = valuesQuery(undefRows());
		LmdbPipelinePlanCache.Result hot = cache.getOrCompute(hotSource, context, context::revision, () -> hotSource);

		assertFalse(cold.cacheHit());
		assertTrue(hot.cacheHit(), "a plan with UNDEF rows must be publishable and reusable");
		assertEquals(1, cache.entryCount());

		BindingSetAssignment installed = (BindingSetAssignment) ((QueryRoot) hot.plan()).getArg();
		List<BindingSet> retainedRows = new ArrayList<>();
		installed.getBindingSets().forEach(retainedRows::add);
		assertEquals(2, retainedRows.size());
		assertEquals(Set.of("x", "y"), installed.getBindingNames());

		BindingSet first = retainedRows.get(0);
		assertFalse(first.hasBinding("x"), "UNDEF cell must stay unbound in the retained template");
		assertNull(first.getValue("x"));
		assertEquals(A, first.getValue("y"));

		BindingSet second = retainedRows.get(1);
		assertEquals(B, second.getValue("x"));
		assertFalse(second.hasBinding("y"), "UNDEF cell must stay unbound in the retained template");
		assertNull(second.getValue("y"));
	}

	@Test
	void singleRowWithEveryCellUndefIsRetained() {
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(8, 1, 1024 * 1024L);
		LmdbPipelinePlanCache.Context context = context(17L);
		List<BindingSet> rows = List.of(new ListBindingSet(List.of("x"), Arrays.asList((IRI) null)));
		QueryRoot coldSource = valuesQuery(rows);

		cache.getOrCompute(coldSource, context, context::revision, () -> {
			coldSource.setStringMetricPlanned(LmdbCascadesOptimizer.APPLIED_METRIC, "true");
			return coldSource;
		});
		QueryRoot hotSource = valuesQuery(rows);
		LmdbPipelinePlanCache.Result hot = cache.getOrCompute(hotSource, context, context::revision, () -> hotSource);

		assertTrue(hot.cacheHit());
		BindingSetAssignment installed = (BindingSetAssignment) ((QueryRoot) hot.plan()).getArg();
		List<BindingSet> retainedRows = new ArrayList<>();
		installed.getBindingSets().forEach(retainedRows::add);
		assertEquals(1, retainedRows.size());
		assertFalse(retainedRows.get(0).hasBinding("x"));
	}

	private static List<BindingSet> undefRows() {
		return List.of(
				new ListBindingSet(List.of("x", "y"), Arrays.asList(null, A)),
				new ListBindingSet(List.of("x", "y"), Arrays.asList(B, null)));
	}

	private static QueryRoot valuesQuery(Iterable<BindingSet> rows) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingNames(Set.of("x", "y"));
		assignment.setBindingSets(rows);
		return new QueryRoot(assignment);
	}

	private static LmdbPipelinePlanCache.Context context(long dataRevision) {
		LmdbEstimatorRuntime.PlanningRevisions planning = new LmdbEstimatorRuntime.PlanningRevisions(
				dataRevision, 2L, 3L, 4L);
		return new LmdbPipelinePlanCache.Context(
				new LmdbPipelinePlanCache.Revision(planning, true), false, 0L,
				LmdbPipelinePlanCache.DatasetIdentity.of(null), LmdbPipelinePlanCache.BindingIdentity.of(null), "",
				false, false, false, "STANDARD", false);
	}
}
